int calls = 0;
var r = await Solution.RetryAsync(() => { calls++; if (calls < 3) throw new InvalidOperationException(); return 42; }, 5, 1);
Cj.Eq(r, 42, "third attempt wins");
Cj.Eq(calls, 3, "three attempts made");

var sw = Stopwatch.StartNew();
var ex = await Cj.ThrowsAsync<InvalidOperationException>(() => Solution.RetryAsync(() => throw new InvalidOperationException(), 3, 50));
sw.Stop();
Cj.True(ex is not null, "the exception must propagate - no sentinel returns");
Cj.True(sw.ElapsedMilliseconds >= 145, $"exponential delays 50+100 = 150ms minimum, got {sw.ElapsedMilliseconds}ms");
